code:
def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False] * n for _ in range(n)]
    min_path = [float('inf')] * k

    def dfs(x, y, path):
        nonlocal min_path
        if len(path) == k:
            if path < min_path:
                min_path = path[:]
            return
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                path.append(grid[nx][ny])
                dfs(nx, ny, path)
                path.pop()
                visited[nx][ny] = False

    for i in range(n):
        for j in range(n):
            visited[i][j] = True
            dfs(i, j, [grid[i][j]])
            visited[i][j] = False

    return min_path

