    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    # Check if n is less than or equal to 1, which are not prime numbers
    if n <= 1:
        return y
    # Check if n is 2, which is the smallest prime number
    elif n == 2:
        return x
    # Check if n is even, which means it's not a prime number
    elif n % 2 == 0:
        return y
    else:
        # If n is odd and greater than 2, check divisibility from 3 up to the square root of n
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return y
        # If no divisors were found, n is a prime number
        return x

