            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    prime_factors = []
    for i in range(2, int(a**0.5) + 1):
        while a % i == 0 and is_prime(i):
            prime_factors.append(i)
            a //= i
