        else:
            frequency[letter] = 1

    # Find the maximum frequency among all letters
    max_freq = max(frequency.values(), default=0)

    # Create a new dictionary to store only the letters with the maximum frequency
    result = {letter: count for letter, count in frequency.items() if count == max_freq}

